const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountEtna = ee.Geometry.Point([14.995, 37.751]); // Mount Etna coordinates
  const buffer = mountEtna.buffer(50000); // 50km buffer around Etna

  // Convert local time to UTC (1:37 am local = 00:37 UTC for Italy in February)
  const startDate = '2021-02-23T00:00:00';
  const endDate = '2021-02-23T01:00:00';

  // 2. Data Acquisition - Use VIIRS for nighttime thermal detection
  const viirs = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterBounds(buffer)
    .filterDate(startDate, endDate);

  const viirsCount = viirs.size().getInfo();
  console.log(`VIIRS Images: ${viirsCount}`);

  if (viirsCount === 0) {
    // Try MODIS as fallback
    const modis = ee.ImageCollection('MODIS/061/MOD14A1')
      .filterBounds(buffer)
      .filterDate(startDate, endDate);

    const modisCount = modis.size().getInfo();
    console.log(`MODIS Images: ${modisCount}`);

    if (modisCount === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Use the first available image
  const image = viirs.size().getInfo() > 0 ? viirs.first() : 
                ee.ImageCollection('MODIS/061/MOD14A1')
                  .filterBounds(buffer)
                  .filterDate(startDate, endDate)
                  .first();

  // 3. Processing - Look for thermal anomalies (fire/hot spots)
  const thermalBand = viirs.size().getInfo() > 0 ? 'MaxFRP' : 'MaxFRP';
  const thermalData = image.select(thermalBand);

  // Create western and eastern regions
  const westRegion = ee.Geometry.Polygon([
    [14.7, 37.8], [14.9, 37.8], [14.9, 37.6], [14.7, 37.6]
  ]);

  const eastRegion = ee.Geometry.Polygon([
    [15.0, 37.8], [15.2, 37.8], [15.2, 37.6], [15.0, 37.6]
  ]);

  // Count thermal anomalies in each region
  const westStats = thermalData.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const eastStats = thermalData.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: eastRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const westCount = westStats.get(thermalBand).getInfo();
  const eastCount = eastStats.get(thermalBand).getInfo();

  console.log(`West region thermal anomalies: ${westCount}`);
  console.log(`East region thermal anomalies: ${eastCount}`);

  // 4. Validation & Final Answer
  if (westCount === null || eastCount === null || 
      (westCount === 0 && eastCount === 0)) {
    console.log("<answer>C2</answer>");
  } else if (westCount > eastCount) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
